// Clean-room TSVC s118 profile; see package rights note.
fn put64(out:[*]u8,p:usize,v:i64)void{const b=@as(u64,@bitCast(v));for(0..8)|j|out[p+j]=@truncate(b>>(8*j));}
pub export fn tsvc_s118_triangular_convolution_recurrence(input:?[*]const i64,length:usize,output:?[*]u8,capacity:usize)i64{if(input==null or length<8 or length>74)return -1;const v=input.?[0..length];const nr=v[0];const passes=v[1];if(nr<2 or nr>8 or passes<1 or passes>4)return -1;const n:usize=@intCast(nr);if(length!=2+n+n*n)return -1;var a=[_]i64{0}**8;var b=[_]i64{0}**64;for(0..n)|i|{if(v[2+i]< -1 or v[2+i]>1)return -1;a[i]=v[2+i];}for(0..n*n)|i|{if(v[2+n+i]< -1 or v[2+n+i]>1)return -1;b[i]=v[2+n+i];}if(output==null or capacity<8*n)return -2;for(0..@as(usize,@intCast(passes))) |_|{for(1..n)|i|{for(0..i)|j|{a[i]+=b[j*n+i]*a[i-j-1];}}}for(0..n)|i|put64(output.?,8*i,a[i]);return @intCast(n);}
